var Gordic;
(function (Gordic) {
    var Gin;
    (function (Gin) {
        var WebClient;
        (function (WebClient) {
            const { gcontent } = Decorators;
            /**
             * Dialog for entering a password for a 602 account (WebClient)
             *
             * @author thazmuka
             * @since 488
             */
            class GEnter602AccountPassword {
                run(parentContent, opt) {
                    //#region --- LOGGER ---
                    var GEnter602AccountPasswordLogger = new Gordic.Diagnostics.GLog({
                        name: "Gordic.Epk.WebControls.GEnter602AccountPassword",
                        fileName: "GEnter602AccountPassword.ts",
                        authorCode: 487
                    });
                    //#endregion
                    //#region --- EVALUATION OF THE DB PARAMETERS, IF THEY ARE TRANSMITTED ---
                    opt = opt == null ? {} : opt;
                    // buď otevření dialogu není povoleno nebo heslo je uloženo v cashi a není potřeba dialog otevřít
                    if (opt.gin_sgn_ssurl === false || opt.gin_ele_602iden === false) {
                        GEnter602AccountPasswordLogger.warn("jres:32000126"); //RC 32000126 : DB parameters are not allowed.
                        return $.Deferred().resolve(false).promise();
                    }
                    //#endregion
                    //#region --- CREATE CONTENT SERVICE ---
                    /** local content */
                    var cnt;
                    if (parentContent != null) {
                        // pokud možno, uložím na parenta, abych ho znovu nevytvářel
                        if (parentContent["GEnter602AccountPasswordService"] == null)
                            parentContent["GEnter602AccountPasswordService"] = new GContent("Gordic.Gin.WebClient.GEnter602AccountPasswordService");
                        cnt = parentContent["GEnter602AccountPasswordService"];
                    }
                    else {
                        cnt = new GContent("Gordic.Gin.WebClient.GEnter602AccountPasswordService");
                    }
                    //#endregion
                    //#region --- LOAD INIT DATA AND OPEN DIALOG ---
                    return cnt.call("Init", { ID: opt.ID })
                        .then((dto) => {
                        opt = opt == null ? {} : opt;
                        dto = dto == null ? {} : dto;
                        //#region --- HTTPS ---
                        // povoleno pouze na HTTPS
                        if (document.location.protocol != 'https:') {
                            GEnter602AccountPasswordLogger.warn("jres:32000124"); //RC 32000124 : HTTPS is not enabled.
                            if (dto.LicAdr !== "DEMO") // v případě DEMO DB nechám projít
                                return $.Deferred().resolve(false).promise();
                        }
                        else {
                            GEnter602AccountPasswordLogger.info("jres:32000125"); //RC 32000125 : HTTPS is enabled.
                        }
                        //#endregion
                        // account setting
                        opt.AccountSetting = dto.AccountSetting;
                        // cached
                        if (dto.AccountSetting === 0) {
                            GEnter602AccountPasswordLogger.info("jres:32000127"); //RC 32000127 : Data of user are cached.
                            return $.Deferred().resolve(true).promise();
                        }
                        // is not allowed by DB parameters
                        if (dto.AccountSetting === 2) {
                            GEnter602AccountPasswordLogger.warn("jres:32000126"); //RC 32000126 : DB parameters are not allowed.
                            return $.Deferred().resolve(false).promise();
                        }
                        // předán doplněný identifikátor
                        opt.ID = dto.ID;
                        // allowed by not cached
                        return this.open(cnt, opt);
                    });
                    //#endregion
                }
                //#region --- OPEN ---
                open(cnt, opt) {
                    let dfd = $.Deferred();
                    var form = this.createForm(opt);
                    var commandbar = this.createCommandbar(form, cnt);
                    // -- vyhodnoceni velikosti okna --
                    var width = 1300;
                    var height = 700;
                    if (cnt.globalSettings != null) {
                        var mobile = cnt.globalSettings.get("Global.Epk.AppSettings.CardGrid");
                        if (mobile === true) {
                            width = window.innerWidth - 50;
                            height = window.innerHeight - 50;
                        }
                    }
                    // ---------------------------------
                    this.modal = cnt.dialogs.showModalWindow(form, null, { title: "jres:32000129", commandBar: commandbar, width: width, height: height, customClass: "GEnter602AccountPassword" }) //RC 32000129 : Zadejte heslo k Vašemu účtu 602
                        .on('close', (ev, retval) => {
                        dfd.resolve(retval === "success" ? true : false);
                    });
                    this.modal.addClass("GEnter602AccountPassword");
                    this.setFocus(form, opt);
                    return dfd.promise();
                }
                setFocus(form, opt) {
                    if (opt.ID != null && opt.ID !== "") // if user exist -> focus on password field
                        form.findFields("password").gfield("focus");
                    else
                        form.findFields("user").gfield("focus"); // if user dont exist -> focus on user field
                }
                createForm(opt) {
                    var form = $("<div>");
                    var Form = new Gordic.Forms.Form({ name: "FormGEnter602AccountPassword" });
                    Form
                        .addSection("jres:32000122"); //RC 32000122 : Údaje
                    Form
                        .addRow("jres:32000116") //RC 32000116 : Důvod
                        .addField("gstringbox", {
                        name: "reason", disabled: true,
                        initialValue: opt.reason == null ? "jres:32000117" : opt.reason, //RC 32000117 : Načtení dostupných certifikátů pro podpis/pečeť
                    });
                    Form
                        .addRow({ label: "jres:32000118", required: true }) //RC 32000118 : Uživatel
                        .addField("gstringbox", { name: "user", validators: [new Gordic.Validators.Required()], initialValue: opt.ID, disabled: (opt.ID != null && opt.ID !== "") ? true : false });
                    Form
                        .addRow({ label: "jres:32000119", required: true }) //RC 32000119 : Heslo
                        .addField("gstringbox", { name: "password", validators: [new Gordic.Validators.Required()], inputType: "password" });
                    form.gform("createFrom", Form);
                    return form;
                }
                createCommandbar(form, cnt) {
                    var params = [];
                    params.push({
                        primary: true,
                        favorite: true,
                        action: new GAction({
                            name: "actOk",
                            caption: "OK",
                            run: (ev) => {
                                this.waitForValues(form)
                                    .then((isValid) => {
                                    if (isValid) {
                                        var model = { user: "", password: "", reason: "" };
                                        form.findFields().gfield("model", "collect", model);
                                        return cnt.call("VerificationAndStore", { ID: model.user, Password: model.password });
                                    }
                                    return $.Deferred().reject().promise();
                                })
                                    .done((res) => {
                                    console.info("Success.");
                                    $.content(this.modal).close("success");
                                })
                                    .fail(() => {
                                    console.error("Fail.");
                                });
                            },
                        })
                    });
                    params.push({
                        action: new GAction({
                            name: "actCancel",
                            caption: "jres:32000121", //RC 32000121 : Zrušit
                            run: (ev) => {
                                $.content(this.modal).close("cancel");
                            },
                        })
                    });
                    return params;
                }
                waitForValues(form) {
                    var dfd = $.Deferred();
                    form.gform("waitForValues")
                        .then(() => {
                        return form.gform("isValid");
                    })
                        .then((isValid) => {
                        dfd.resolve(isValid);
                    })
                        .fail(() => {
                        dfd.reject(false);
                    });
                    return dfd.promise();
                }
            }
            WebClient.GEnter602AccountPassword = GEnter602AccountPassword;
        })(WebClient = Gin.WebClient || (Gin.WebClient = {}));
    })(Gin = Gordic.Gin || (Gordic.Gin = {}));
})(Gordic || (Gordic = {}));
