                constructor(canvasId, dimensions, options) {
                    super(canvasId, dimensions, options);
                    if (canvasId instanceof GAIVisualiserShape) {
                        this.item = canvasId.item;
                        this.caption = canvasId.caption;
                        this.valueText = canvasId.valueText;
                        this.canExecute = canvasId.canExecute;
                    }
                }
                copy() {
                    return new GAIVisualiserShape(this);
                }
