            class GAIVisualiserShapeDrawer extends Gordic.Components.CanvasDrawer.GBaseShapeDrawer {
                constructor() {
                    super();
                    this.on('save', (ctx) => {
                        ctx.shape.resizable = false;
                        ctx.shape.draggable = false;
                    });
                }
                createShape(canvasId) {
                    return new GAIVisualiserShape(canvasId);
                }
                drawCanvas(canvas, shape) {
                    const canvasContext = canvas.getContext('2d');
                    if (canvasContext) {
                        //canvasContext.lineWidth = 5;
                        const probability = parseDecimal(shape.item.pravdepodobnost ?? 0);
                        if (probability.gte(0.9))
                            // canvasContext.strokeStyle = 'green';
                            canvasContext.fillStyle = "rgba(32.5,175,112.5,0.4)";
                        else if (probability.gte(0.7))
                            // canvasContext.strokeStyle = 'blue';
                            canvasContext.fillStyle = "rgba(0,0,255,0.4)";
                        else if (probability.gte(0.3))
                            // canvasContext.strokeStyle = 'orange';
                            canvasContext.fillStyle = "rgba(0,0,255,0.4)";
                        else
                            canvasContext.fillStyle = "rgba(255,0,0,0.4)";
                        //  canvasContext.strokeStyle = 'red';
                        //canvasContext.strokeRect(shape.x, shape.y, shape.width, shape.height);
                        canvasContext.fillRect(shape.x, shape.y, shape.width, shape.height);
                    }
                }
            }
