                        //        //$.newDiv().html(Gordic.Prefabs.Utils.getDoubleLineInfo({ info: ctx.shape.data.item.ValueString ?? "", more: ctx.shape.data.alternateItemTxt ?? ctx.shape.data.item.ItemTxt ?? "?" }))
                        //        //$.newDiv(Components.CanvasDrawer.ignoreActiveCancelationClass, "gaivisualiser-detail")
                        //        //.append($.newDiv().attr("role","heading").text(ctx.shape.data.alternateItemTxt ?? ctx.shape.data.item.ItemTxt ?? "?"))
