                    createAppSelectBox() {
                        const { llmDataModel, chatAppSelectDummyFieldName, conversationFormName, conversationFeildName } = this;
                        const initialChatApp = this.aiChatAppsPromise
                            .then(apps => {
                            this.lastSelectedAppIxsLap = llmDataModel.selectedChatApp?.IxsLap ?? "";
                            const initial = llmDataModel.selectedChatApp ?? apps[0] ?? { IxsLap: "" };
                            return initial;
                        });
                        this.$chatAppSelectBox = $.newDiv()
                            .gselectbox({
                            name: "chatAppSelect",
                            //data: this.aiChatAppsPromise,
                            data: this.aiChatAppsDataViewPromise,
                            dropdown: true,
                            strict: true,
                            helperColumns: ["Desc", "DescLong"],
                            initialValue: initialChatApp,
                            validators: [
                                new Gordic.Validators.Required({
                                    message: "jres:35000005", //RC 35000005 : AI aplikace nesmí zůstat prázdná.
                                    validate: (val, src) => {
                                        return !!(val?.IxsLap);
                                    }
                                }), //RC 35000005 : AI aplikace nesmí zůstat prázdná.
                            ],
                            itemTemplate: "{Desc:encode}",
                            helperItemTemplate: (item) => Gordic.Prefabs.Utils.getDoubleLineInfo({
                                infoElement: item.Desc ?? "",
                                moreElement: "<i>{0}</i>".format(item.DescLong ?? "jres:35000006") //RC 35000006 : AI Asistent
                            }),
                            itemTooltipTemplate: (val) => val.DescLong ?? "",
                            change: (ev, input) => {
                                const selected = input?.value;
                                if (!selected) {
                                    return;
                                }
                                if (selected.IxsLap === this.lastSelectedAppIxsLap) {
                                    return; // fieldchange je volaný každým apply, nemá cenu překleslit stejná data
                                }
                                this.lastSelectedAppIxsLap = selected.IxsLap ?? "";
                                this.cacheRecordRef.llmDataModel.selectedChatApp = selected;
                                this.beginOperation();
                                this.getScenariosDataAsync(selected) // new scenarios / change order
                                    .then(scenarios => this.createScenariosChildernMenuParams(scenarios))
                                    .then(menuParams => {
                                    this.element.findFields(conversationFeildName).gfield("setValue", this.llmDataModel.conversation);
                                    this.findFields(chatAppSelectDummyFieldName).gfield("setValue", input.value);
                                    this.findForms(conversationFormName).gform().gautofit({ resizersOnTab: false });
                                })
                                    .always(() => this.endOperation());
                            }
                        })
                            .css("min-width", "180px");
                        return this.$chatAppSelectBox;
                    }
