                            name: "selectedAttachmentViewModels",
                            data: this.attachmentsView,
                            //Na políčku se v žádném případě JQE nesmí objevit
                            model: "model.selectedAttachmentViewModels=value;" +
                                "model.selectedAttachmentsDefinitions<=value;",
