                    subscribeCallbacks() {
                        this.attViewCallback = () => {
                            const newDefinitions = this.attachmentDispatcher.items;
                            this.attachmentsDefMap = {};
                            newDefinitions.forEach(def => { this.attachmentsDefMap[def.id] = def; });
                            const newViews = newDefinitions.map((d) => {
                                return { caption: d.caption, id: d.id, idCache: d.idCache };
                            });
                            this.attachmentsView.updateData(newViews);
                            this.collectModel(); // asi by to chtělo mít dispečera jako eventy a collect volat jen na update
                        };
                        this.scenarioCallback = () => {
                            //TODO: pdohnal - zpřístupňovat scénáře podle dostupnosti příloh
                        };
                        this.attViewCallback(); // prvni update
                        this.attachmentDispatcher.subscribe(this.attViewCallback);
                        this.attachmentDispatcher.subscribe(this.scenarioCallback);
                    }
                    registerMessageEvents() {
                        const ns = "." + GAiChatSubcontent.CSS_CLASS_NAME;
                        // Include all roles you want interactive
                        const selector = [`.${"gaichat-ai-answer" /* ChatCssStylesRolesEnum.AiMessage */}`].join(",");
                        this.element
                            .on("mouseenter" + ns, selector, (ev) => this.onHoverEnter(ev))
                            .on("mouseleave" + ns, selector, (ev) => this.onHoverLeave(ev));
                    }
                    onHoverEnter(ev) {
                        const $msg = $(ev.currentTarget);
                        const llmMessage = $msg.data("llmMessage");
                        if (!llmMessage) {
                            return;
                        }
                        // Disabled (other app) – no toolbar
                        if ($msg.attr("data-gaichat-disabled") === "1") {
                            return;
                        }
                        // If the gstaticfield is disabled pointer events may be suppressed.
                        // Override locally (only once).
                        if ($msg.css("pointer-events") === "none") {
                            $msg.css("pointer-events", "auto");
                        }
                        const toolbarClass = "gaichat-toolbar";
                        // Already exists?
                        if ($msg.children("." + toolbarClass).length > 0) {
                            this.trigger(GAiChatSubcontentEvents.ChatMessageEnter, [llmMessage, ev, $msg]);
                            return;
                        }
                        const menuParams = [
                            {
                                action: this.actions["actCopyToClipboard" /* Acts.CopyToClipboard */],
                                actionContext: { str: llmMessage.content }
                            }
                        ];
                        // Ensure parent can host absolute positioned child
                        if ($msg.css("position") === "static") {
                            $msg.css("position", "relative");
                        }
                        $.newDiv(toolbarClass)
                            .css({
                            position: "inherit",
                            bottom: "30px",
                            background: "rgba(255,255,255,0.95)",
                            border: "1px solid #d0d0d0",
                            //padding: "2px 4px",
                            borderRadius: "4px",
                            fontSize: "11px",
                            display: "flex",
                            gap: "4px",
                            zIndex: 1000,
                            pointerEvents: "auto"
                        })
                            .appendTo($msg)
                            .gbuttonpanel({ params: menuParams, mode: "link" });
                        this.trigger(GAiChatSubcontentEvents.ChatMessageEnter, [llmMessage, ev, $msg]);
                    }
                    onHoverLeave(ev) {
                        const $msg = $(ev.currentTarget);
                        // Remove toolbar when leaving
                        $msg.children(".gaichat-toolbar").remove();
                        this.trigger(GAiChatSubcontentEvents.ChatMessageLeave, [$(ev.currentTarget).data("llmMessage"), ev, $msg]);
                    }
                    createScenariousFormAsync(selectedChatApp) {
                        return this.getScenariosDataAsync(selectedChatApp)
                            .then(scenarios => this.createScenariosChildernMenuParams(scenarios));
                    }
                    /**
                     * Získá scénáře od DB a od programátorů
                     * @param selectedChatApp
                     * @returns
                     */
                    getScenariosDataAsync(selectedChatApp) {
                        const req = { scenarios: [] };
                        this.trigger(GAiChatSubcontentEvents.ScenariosRequest, [req]);
                        if (!selectedChatApp || selectedChatApp?.IxsLap?.length === 0) {
                            return $.when().then(() => []);
                        }
                        return this.aiChatAppsPromise
                            .then(chatApps => [
                            selectedChatApp,
                            ...chatApps.filter(app => app.IxsLap !== selectedChatApp.IxsLap)
                        ])
                            .then(apps => apps.length > 0
                            ? this.isl.AiChatApps.getAllChatScenariosDtoList({
                                ixsLaps: apps.map(app => app.IxsLap ?? "").filter(Boolean),
                                content: this.aiContentType
                            })
                                .get()
                                .then(scens => { return { apps: apps, scens: scens }; })
                            : { apps: [], scens: [] })
                            .then(appsAndSceners => {
                            const dbScens = appsAndSceners.scens.map((s, idx) => {
                                return {
                                    //ixsLap: s.IxsLap ?? "",
                                    //ixsLap: selectedChatApp?.IxsLap ?? "",
                                    caption: s.Caption ?? "",
                                    captionLong: s.CaptionLong ?? "",
                                    prompt: s.Prompt ?? "",
                                    chatApp: appsAndSceners.apps.find(app => app.IxsLap === s.IxsLap),
                                    name: "dbPredefined{0}".format(idx),
                                    requestAttachments: ["files"],
                                };
                            });
                            req.scenarios.unshift(...dbScens); // pokud by něco přišlo od programátora a né z DB, mělo by to být na konci
                            return req.scenarios;
                        });
                    }
                    createScenariosChildernMenuParams(scenarios) {
                        if (scenarios.length === 0) {
                            return [];
                        }
                        let lastIxsLap = scenarios[0].chatApp?.IxsLap ?? "";
                        const formatSelectedApp = (info) => {
                            return `<b>${info}</b>`;
                        };
                        const createAppChildern = (sc) => {
                            return sc.chatApp?.IxsLap === this.lastSelectedAppIxsLap
                                ? {
                                    type: "action",
                                    action: this.actions["actScenario" /* Acts.Scenario */],
                                    actionContext: sc,
                                    caption: Gordic.Prefabs.Utils.getDoubleLineInfo({
                                        infoElement: formatSelectedApp(`${(sc.chatApp?.AppName) ?? 'jres:35000021'}: ${sc.caption}` //RC 35000021 : Ostatní
                                        ),
                                        moreElement: "<i>{0}</i>".format(sc.captionLong)
                                    }),
                                }
                                : {
                                    type: "action",
                                    action: this.actions["actScenarioAppSwitch" /* Acts.ScenarioAppSwitch */],
                                    actionContext: sc,
                                    caption: Gordic.Prefabs.Utils.getDoubleLineInfo({
                                        infoElement: `${(sc.chatApp?.AppName) ?? 'jres:35000021'}: ${sc.caption}`, //RC 35000021 : Ostatní
                                        moreElement: "<i>{0}</i>".format(sc.captionLong)
                                    }),
                                };
                        };
                        const createSeparator = () => {
                            return { type: "separator" };
                        };
                        const childernMenuParams = [];
                        scenarios.forEach(sc => {
                            const scIxsLap = sc.chatApp?.IxsLap ?? "";
                            const ixsLapHasChanged = lastIxsLap !== scIxsLap;
                            if (ixsLapHasChanged) {
                                lastIxsLap = scIxsLap;
                                childernMenuParams.push(createSeparator());
                            }
                            childernMenuParams.push(createAppChildern(sc));
                        });
                        this.scenariosLinkMenuParamsObs.update({ children: childernMenuParams });
                        return childernMenuParams;
                    }
                    /**
                     * starý pro načítání scénářů jako linků do section
                     * @deprecated
                     */
                    createScenariosFormWithSectionView(scenarios) {
                        const { scenariousFormName, scenarioLinkName } = this;
                        const form = new Gordic.Forms.Form({ name: scenariousFormName, layoutDescriptor: "L1M1S1, L-12-12-0, M-12-12-0, S-12-12-0" })
                            .addSection("jres:35000013"); //RC 35000013 : Vzorové prompty
                        for (let sc of scenarios) {
                            form
                                .addField("glink", {
                                name: `${scenarioLinkName}${sc.name}`,
                                params: {
                                    action: this.actions["actScenario" /* Acts.Scenario */],
                                    actionContext: sc,
                                    caption: sc.caption
                                }
                            })
                                .addText(sc.captionLong);
                        }
                        return form;
                    }
                    //private showConvHistModalWindow(): void {
                    //    this.findForms().gform("waitForValues").then(() => {
                    //        const { llmDataModel } = this;
                    //        const { predictedAnswers } = llmDataModel;
                    //        if (predictedAnswers.length === 0) {
                    //            this.showFlash({ content: "jres:35000014", id: "aichat-conv-empty" }); //RC 35000014 : Konverzace je prázdná.
                    //            return;
                    //        }
                    //        const contentInit = [GAiChatSubcontentHistModal, { messages: predictedAnswers }];
                    //        this.dialogs.showModalWindow(contentInit, undefined, {
