                static CreateNameWithScope(name, scope) {
                    // 19.01.2023 - TFeik
                    // Změna separátoru z '.' na '__'.
                    return GSharedIsl.ApplyScope(name, scope, GSharedIsl.NameSeparator);
                }
                static CreateFragmentWithScope(name, scope) {
                    return GSharedIsl.ApplyScope(name, scope);
                }
                static CreateFilterNameWithScope(name, scope) {
                    // 23.01.2023 - TFeik
                    // Pro tuhle úpravu bych napřd musel informovat ty co už náhodou používajízanořeně filtry dokumentu,
                    // aby v enumech filtru nahradili '_' za '__', tak to nehám jak to bylo.
                    // 19.01.2023 - TFeik
                    // Sjednocení vytváření názvů.
                    //return GSharedIsl.CreateNameWithScope(name, scope);
                    return GSharedIsl.ApplyScope(name, scope, '_');
                }
                static CreateFilterNameWithScopeFromInput(name, input) {
                    return GSharedIsl.CreateFilterNameWithScope(name, input?.scopeLevels?.map(i => i?.scope).filter(i => i?.trim()));
                }
                static CreateTitleWithScope(title, scopeTitle, separator) {
                    return GSharedIsl.ApplyScope(title, scopeTitle, separator ?? ' - ');
                }
                static CreateTitleWithScopeFromInput(title, input) {
                    return GSharedIsl.CreateTitleWithScope(title, input?.scopeLevels?.map(i => i?.scopeTitle).filter(i => i?.trim()), input?.scopeTitleSeparator);
                }
                static CreateNameWithScopeFromInput(columnName, input) {
                    return GSharedIsl.CreateNameWithScope(columnName, input?.scopeLevels?.map(i => i?.scope).filter(i => i?.trim()));
                }
                static CreateFragmentWithScopeFromInput(columnName, input) {
                    return GSharedIsl.CreateFragmentWithScope(columnName, input?.scopeLevels?.map(i => i?.scope).filter(i => i?.trim()));
                }
                static ApplyScopeToGridColumns(gridColumn, scopeOptions) {
                    if (gridColumn?.name?.trim()) {
                        gridColumn.name = GSharedIsl.CreateNameWithScopeFromInput(gridColumn.name, scopeOptions);
                    }
                    if (gridColumn?.fragment?.trim()) {
                        gridColumn.fragment = GSharedIsl.CreateFragmentWithScopeFromInput(gridColumn.fragment, scopeOptions);
                    }
                    if (gridColumn?.caption?.trim()) {
                        gridColumn.caption = GSharedIsl.CreateTitleWithScopeFromInput(gridColumn.caption, scopeOptions);
                    }
                    if (gridColumn?.field?.trim()) {
                        gridColumn.field = GSharedIsl.CreateFragmentWithScopeFromInput(gridColumn.field, scopeOptions);
                    }
                    const scopes = scopeOptions?.scopeLevels?.map(i => i?.scope)?.filter(i => i.trim());
                    if (scopes && scopes.length > 0) {
                        gridColumn.scope = scopes.join(GSharedIsl.ScopeSeparator);
                    }
                    return gridColumn;
                }
                static CreateSubentityColumnName(scope, subentityColumnName) {
                    return [scope, subentityColumnName].join(GSharedIsl.NameSeparator);
                }
                /**
                 * Vrátí ikony pro aktivitu.
                 *
                 * @param {Gordic.Ginis.DbModel.GGincaktEnum | null} [value]
                 * @returns {string}
                 */
                static GetGincaktEnumIcon(value) {
                    switch (value) {
                        case 100 /* Gordic.Ginis.DbModel.GGincaktEnum.aktivni */:
                            return 'gi-tick';
                        case 600 /* Gordic.Ginis.DbModel.GGincaktEnum.navrh */:
                            return 'gi-plus';
                        case 500 /* Gordic.Ginis.DbModel.GGincaktEnum.neaktivni */:
                            return 'gi-minus';
                        case 300 /* Gordic.Ginis.DbModel.GGincaktEnum.pripraven */:
                            return 'fa-check-square-o';
                        case 900 /* Gordic.Ginis.DbModel.GGincaktEnum.zrusen */:
                            return 'fa-times';
                        default:
                            return 'gi-question';
                    }
                }
                /**
                 * Vrátí IconTemplate pro aktivitu.
                 *
                 * @param {Gordic.Ginis.DbModel.GGincaktEnum | null} [value]
                 * @returns {IconTemplate}
                 */
                static GetGincaktEnumIconTemplate(value) {
                    const iconTemplate = {
                        icon: GSharedIsl.GetGincaktEnumIcon(value)
                    };
                    switch (value) {
                        case 100 /* Gordic.Ginis.DbModel.GGincaktEnum.aktivni */:
                            iconTemplate.text = 'jres:32110303'; //RC 32110303 : Aktivní
                            break;
                        case 600 /* Gordic.Ginis.DbModel.GGincaktEnum.navrh */:
                            iconTemplate.text = 'jres:32110304'; //RC 32110304 : Návrh
                            break;
                        case 500 /* Gordic.Ginis.DbModel.GGincaktEnum.neaktivni */:
                            iconTemplate.text = 'jres:32110305'; //RC 32110305 : Neaktivní
                            break;
                        case 300 /* Gordic.Ginis.DbModel.GGincaktEnum.pripraven */:
                            iconTemplate.text = 'jres:32110306'; //RC 32110306 : Připraven
                            break;
                        case 900 /* Gordic.Ginis.DbModel.GGincaktEnum.zrusen */:
                            iconTemplate.text = 'jres:32110307'; //RC 32110307 : Zrušen
                            break;
                        default:
                            iconTemplate.text = 'jres:32110308'; //RC 32110308 : Neznámý stav
                            break;
                    }
                    if (iconTemplate.tooltip == null && iconTemplate.text) {
                        iconTemplate.tooltip = iconTemplate.text;
                    }
                    return iconTemplate;
                }
                /**
                 * Vrátí IconTemplate pro Typ přihlášení.
                 *
                 * @param {Gordic.Ginis.DbModel.GGinczmpEnum | null} [value]
                 * @returns {IconTemplate}
                 */
                static GetGinczmpEnumIconTemplate(value) {
                    switch (value) {
                        case 10 /* Gordic.Ginis.DbModel.GGinczmpEnum.Radne_obsazeni */:
                            return {
                                icon: 'gi-user',
                                text: 'jres:32110309', //RC 32110309 : Řádné obsazení
                                tooltip: 'jres:32110309' //RC 32110309 : Řádné obsazení
                            };
                        case 20 /* Gordic.Ginis.DbModel.GGinczmpEnum.Zastup */:
                            return {
                                icon: 'gi-users',
                                text: 'jres:32110310', //RC 32110310 : Zástup
                                tooltip: 'jres:32110310' //RC 32110310 : Zástup
                            };
                        default:
                            return {
                                icon: 'gi-question',
                                text: 'jres:32110308', //RC 32110308 : Neznámý stav
                                tooltip: 'jres:32110308' //RC 32110308 : Neznámý stav
                            };
                    }
                }
                /**
                 * FilterNamesWithScope<TName extends string, TSubnames extends string>
                 *
                 * @param {TName[] | 'all' | undefined | null} names
                 * @param {string} scope
                 * @returns {TSubnames[] | 'all' | undefined}
                 */
                static FilterNamesWithScope(names, scope, 
                /**
                 * Pokud není vyplněno, pak se zjistí dle names.
                 * @type {AddMode}
                 */
                addMode) {
                    if (!names || names === 'all') {
                        return names ?? void 0;
                    }
                    if (!addMode) {
                        addMode = GSharedIsl.GetAddMode(names);
                    }
                    // Možnost in/excludnout celý podřízený objekt.
                    if (names.includes(scope)) {
                        switch (addMode) {
                            case 'optOut':
                                return false;
                            case 'optIn':
                            default:
                                return 'all';
                        }
                    }
                    const scopeText = `${scope}${GSharedIsl.NameSeparator}`;
                    const scopeNames = names
                        .filter(i => i.indexOf(scopeText) === 0)
                        .map(i => i.replace(scopeText, ''));
                    if (addMode === 'optOut') {
                        const result = [];
                        if (!scopeNames.includes(GSharedIsl.Exclude)) {
                            result.push(GSharedIsl.Exclude);
                        }
                        return $.merge(result, scopeNames);
                    }
                    return scopeNames;
                }
                static CanAdd(item, items, 
                /**
                 * Pokud není vyplněno, pak se zjistí dle items.
                 * @type {AddMode}
                 */
                addMode) {
                    if (items == null || items === 'all') {
                        return true;
                    }
                    if (items === false) {
                        return false;
                    }
                    const includes = items.includes(item);
                    switch (addMode ?? GSharedIsl.GetAddMode(items)) {
                        case 'optOut':
                            return !includes;
                        case 'optIn':
                        default:
                            return includes;
                    }
                }
                static GetAddMode(items) {
                    return GSharedIsl.IsOptOutMode(items) ? 'optOut' : 'optIn';
                }
                static IsOptOutMode(items) {
                    if (!items || items === 'all') {
                        return false;
                    }
                    return items.includes(GSharedIsl.Exclude);
                }
